import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百五十二章 如来的正法不是用来比试的","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/152第一百五十二章 如来的正法不是用来比试的.md","filePath":"meditation/巴利文大藏经/152第一百五十二章 如来的正法不是用来比试的.md"}'),o={name:"meditation/巴利文大藏经/152第一百五十二章 如来的正法不是用来比试的.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第一百五十二章-如来的正法不是用来比试的" tabindex="-1">第一百五十二章 如来的正法不是用来比试的 <a class="header-anchor" href="#第一百五十二章-如来的正法不是用来比试的" aria-label="Permalink to &quot;第一百五十二章 如来的正法不是用来比试的&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部16相应6经/教诫经(迦叶相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的竹林中，有一天，迦叶尊者来到佛陀的住所，他顶礼佛陀后，就在一旁坐下，佛陀对迦叶尊者说：“迦叶！你可以教导僧团里面的出家人，你可以给这些出家人说法，你可以像如来一样对僧团里面的出家人说法，教导他们。”</p><p>迦叶尊者说：“世尊，现在僧团里面的出家人是很难教导的，就算我对他们说法了，他们也不会听我的，也不会去纠正他们自己的错误的，现在僧团里面能够直面自己错误，坦率接受别人正确的建议，并去忏悔改错的出家人已经很少了。</p><p>世尊，我就曾经看见阿难尊者的弟子班达比丘（出家人），他与阿那律尊者的弟子阿宾吉伽比丘，互相的比试、挑战谁说的法更多，谁说的法更好，谁说法的时间更长。</p><p>我前去制止他们愚昧的行为，他们还反过来讥讽我不学无术，他们还说：「如果迦叶你有真本事的话，就与我们比试说法。」我见他们不接受我的建言，于是就离开了。”</p><p>那时，佛陀听完迦叶尊者的言语，就叫来一位出家人，对他说：“比丘（出家人）！你以如来的名义去叫阿难尊者的弟子班达比丘和阿那律尊者的弟子阿宾吉伽比丘，到如来这里来。”</p><p>那位出家人回答：“世尊，好的，我现在就去叫他们来。”</p><p>没有过多长时间，班达比丘和阿宾吉伽比丘就来到佛陀的住所，他们顶礼佛陀后，就在一旁坐下。</p><p>佛陀对他们说：“班达！阿宾吉伽！这件事情是真的吗？你们两人在互相比试、挑战谁说的法更多，谁说的法更好，谁说法的时间更长，是这样吗？”</p><p>班达比丘和阿宾吉伽比丘回答：“世尊，我们确实在互相比试、挑战说法，我们想这样能够分出学法的高下，能够分清楚谁学法学的更好。”</p><p>佛陀说：“班达！阿宾吉伽！你们回想一下，如来曾经教导过你们：「来，我们来互相比试、挑战谁说的法更多，谁说的法更好，谁说法的时间更长」吗？如来对你们说过这样的法吗？”</p><p>班达比丘和阿宾吉伽比丘回答：“世尊，你没有这样说过法。”</p><p>佛陀说：“班达！阿宾吉伽！如来并没有说过让比丘互相比试、挑战说法的法，你们这样去做只会让自己陷入争斗的陷阱之中，只会让你们生起争斗的烦恼。如来的正法是用来除灭烦恼和痛苦的，而不是用来增加烦恼和痛苦的，你们现在陷入争斗的陷阱之中，你们现在在争斗的烦恼中挣扎还不自知。你们真是愚痴的人，你们已经忘失如来的教导，已经离如来的正法越来越远了。”</p><p>班达比丘和阿宾吉伽比丘这时，立刻就将他们的头顶礼在佛陀的脚上，请求佛陀的原谅，他们对佛陀说：“世尊，我们是如此的愚昧无知，陷入争斗的陷阱中，我们沉浸在争斗的烦恼中还不自知，还自认为高明，还自认为在精进的修行。敬请世尊您原谅我们，我们会立刻纠正我们错误的行为，我们将会在僧团里面虔诚的忏悔我们错误的行为的。”</p><p>佛陀说：“班达！阿宾吉伽！你们确实犯了过错，你们确实被无知障碍，你们互相比试、挑战谁说的法更多，谁说的法更好，谁说法的时间更长，让很多僧团里面的出家人效法、学习，让很多出家人都陷入了争斗的陷阱中，让很多的出家人都生起了争斗的烦恼，不过你们现在在如来这里虔诚的忏悔，你们也准备到僧团中去虔诚的忏悔，并纠正你们错误的行为。如来原谅你们，僧团也会原谅你们的。班达！阿宾吉伽！你们要明白，认识到了自己的错误，并虔诚的忏悔，以后不再去犯同样的错误，就是回到了正确的修行道路上，这样就是受持好了如来制定的戒律，虽然你们曾经犯过错误，但是你们知道纠正自己的错误，知道用如来制定的戒律去制止这样的错误不再发生，你们犯错造下的罪业将会慢慢的消退，你们虔诚忏悔纠正错误，不再犯同样的错误，并按如来的正法去修行种植下的功德将会持续的增长。”</p><p>佛陀说法后，班达比丘和阿宾吉伽比丘，以及在场听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',18)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
